'use strict';
(()=>{
 const bar=document.createElement('div');bar.className='session-bar';bar.innerHTML='<span id="sessionIdentity">正在检查登录</span><button class="outline" id="logoutButton">退出登录</button>';document.querySelector('main header').prepend(bar);
 const panel=document.createElement('article');panel.className='panel';panel.id='memberSettings';panel.innerHTML=`<div class="panel-head"><div><h2>成员与登录设置</h2><p id="accountIdentity"></p></div></div>
 <details><summary>修改我的密码</summary><form id="passwordForm" class="form-grid"><label class="field full">当前密码<input id="currentPassword" type="password" autocomplete="current-password"></label><label class="field">新密码<input id="newPassword" type="password" autocomplete="new-password"></label><label class="field">再次输入新密码<input id="confirmNewPassword" type="password" autocomplete="new-password"></label><button class="solid full" type="submit">修改我的密码</button></form><p id="passwordStatus" role="status"></p><p class="muted">密码没有长度或字符组合要求。修改后本人的设备需要重新登录。</p></details>
 <div id="adminMemberTools" hidden><h3>家庭成员</h3><div id="memberList"></div><details><summary>添加成员</summary><form id="addMemberForm" class="form-grid"><label class="field">成员称呼<input id="newMemberName" required maxlength="40"></label><label class="field">登录名<input id="newMemberUsername" required pattern="[A-Za-z0-9._-]{3,40}"></label><label class="field">初始密码<input id="newMemberPassword" type="password" autocomplete="new-password"></label><label class="field">再次输入密码<input id="newMemberConfirm" type="password" autocomplete="new-password"></label><label class="field">性别（可选）<select id="newMemberGender"><option value="unspecified">不指定</option><option value="male">男</option><option value="female">女</option></select></label><label class="field full">权限<select id="newMemberRole"><option value="member">普通成员</option><option value="admin">管理员</option></select></label><button class="solid full" type="submit">添加成员</button></form></details>
 <details><summary>重设成员密码 / 移除成员</summary><form id="resetMemberForm" class="form-grid"><label class="field full">选择成员<select id="targetMember"></select></label><label class="field">新密码<input id="memberResetPassword" type="password" autocomplete="new-password"></label><label class="field">再次输入新密码<input id="memberResetConfirm" type="password" autocomplete="new-password"></label><button class="solid full" type="submit">重设这位成员的密码</button></form><label><input id="removeMemberAgree" type="checkbox"> 确认移除所选成员的登录权限，历史账目保留</label><button id="removeMember" class="outline" type="button">移除所选成员</button></details>
 <details><summary>管理员密码恢复卡</summary><p>忘记密码时，在登录页使用恢复码即可重设。重新生成会使旧恢复码失效。</p><button class="outline" id="renewRecovery" type="button">生成我的恢复卡</button><code class="recovery-code" id="settingsRecovery"></code><button class="outline" id="downloadRecovery" type="button" hidden>下载恢复卡</button></details><p class="muted">管理员可管理成员、重开已关账月份及恢复账本；普通成员共用家庭账目并可填报。</p></div><p id="memberStatus" role="status"></p>`;
 document.querySelector('[data-page="settings"]').prepend(panel);
 const palette=[['#168bd2','海蓝'],['#df5987','玫瑰'],['#8b64e8','紫罗兰'],['#19a58b','青绿'],['#e49a28','琥珀'],['#cf654b','珊瑚']];
 function colorPicker(value,onChange){const box=document.createElement('div');box.className='member-colors';box.setAttribute('role','group');box.setAttribute('aria-label','成员图表配色');const title=document.createElement('span');title.textContent='图表配色';box.append(title);for(const [color,name]of palette){const b=document.createElement('button');b.type='button';b.title=name;b.setAttribute('aria-label',name);b.style.setProperty('--swatch',color);b.setAttribute('aria-pressed',String(color===value));b.onclick=()=>{for(const n of box.querySelectorAll('button'))n.setAttribute('aria-pressed',String(n===b));onChange(color);};box.append(b);}return box;}
 let newColor=palette[0][0];$('newMemberGender').parentElement.after(colorPicker(newColor,c=>newColor=c));
 let me=null,recovery='';const channel=typeof BroadcastChannel==='undefined'?null:new BroadcastChannel('family-auth');if(channel)channel.onmessage=()=>location.replace('/login?expired');
 async function loadMembers(){if(me?.role!=='admin')return;const r=await api('/api/members');$('memberList').replaceChildren();$('targetMember').replaceChildren();for(const m of r.members){const p=document.createElement('p');p.textContent=`${m.name} · ${m.username} · ${m.role==='admin'?'管理员':'普通成员'}${m.active?'':' · 已移除，历史账目保留'}`;if(m.active){const gender=document.createElement('select');gender.setAttribute('aria-label',m.name+'配色标记');for(const [v,t]of [['unspecified','不指定'],['male','男'],['female','女']])gender.append(new Option(t,v));gender.value=D.memberProfiles?.find(p=>p.key===m.member)?.gender||'unspecified';let selectedColor=D.memberProfiles?.find(p=>p.key===m.member)?.color||FamilyChartAxis.memberColor(D.memberProfiles?.find(p=>p.key===m.member),r.members.indexOf(m));const picker=colorPicker(selectedColor,c=>selectedColor=c);const save=document.createElement('button');save.className='outline';save.textContent='保存配色';save.type='button';save.onclick=()=>memberAction(()=>api('/api/members/profile',{member:m.member,gender:gender.value,color:selectedColor}));p.append(gender,picker,save);}$('memberList').append(p);if(m.active)$('targetMember').append(new Option(`${m.name}（${m.username}）`,m.id));}}
 async function check(){try{const r=await fetch('/api/auth/status');if(!r.ok)return;const s=await r.json();if(!s.signedIn){location.replace('/login?expired');return;}me=s.user;window.currentFamilyUser=me;$('sessionIdentity').textContent=`${me.name} · ${me.role==='admin'?'管理员':'成员'}`;$('accountIdentity').textContent=`登录名：${me.username}。收入归属可选择其他家人；所有成员共用家庭账目。`;$('adminMemberTools').hidden=me.role!=='admin';await loadMembers();document.dispatchEvent(new Event('family-session-ready'));}catch(e){$('memberStatus').textContent=e.message;}}
 $('logoutButton').onclick=async()=>{await api('/api/auth/logout',{});channel?.postMessage('logout');location.replace('/login');};
 $('passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/password',{currentPassword:$('currentPassword').value,newPassword:$('newPassword').value,confirmPassword:$('confirmNewPassword').value});channel?.postMessage('password');location.replace('/login?changed');}catch(x){$('passwordStatus').textContent=x.message;}};
 async function memberAction(action){$('memberStatus').textContent='正在处理…';try{await action();await refreshLedger();await loadMembers();$('memberStatus').textContent='已保存。';}catch(e){$('memberStatus').textContent=e.message;}}
 $('addMemberForm').onsubmit=e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;memberAction(async()=>{await api('/api/members/add',{name:$('newMemberName').value,username:$('newMemberUsername').value,password:$('newMemberPassword').value,confirmPassword:$('newMemberConfirm').value,gender:$('newMemberGender').value,color:newColor,role:$('newMemberRole').value});$('addMemberForm').reset();}).finally(()=>b.disabled=false);};
 $('resetMemberForm').onsubmit=e=>{e.preventDefault();const target=$('targetMember').value;memberAction(async()=>{await api('/api/members/reset-password',{id:target,newPassword:$('memberResetPassword').value,confirmPassword:$('memberResetConfirm').value});$('memberResetPassword').value=$('memberResetConfirm').value='';if(target===me.id)location.replace('/login?changed');});};
 $('removeMember').onclick=()=>{if(!$('removeMemberAgree').checked){$('memberStatus').textContent='请先勾选确认移除。';return;}memberAction(async()=>{await api('/api/members/remove',{id:$('targetMember').value});$('removeMemberAgree').checked=false;});};
 $('renewRecovery').onclick=()=>memberAction(async()=>{const r=await api('/api/auth/recovery-code',{});recovery=r.recoveryCode;$('settingsRecovery').textContent=recovery;$('downloadRecovery').hidden=false;});
 $('downloadRecovery').onclick=()=>download('家有数_管理员恢复卡.txt',`网址：${location.origin}\n管理员：${me.username}\n恢复码：${recovery}\n请私下保存。重新生成后旧码失效。`,'text/plain;charset=utf-8');
 window.addEventListener('focus',check);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check();});setInterval(check,60000);check();
})();
